import Foundation

// Worker-protocol HTTP client. Same wire shapes as the iOS app's
// LobuClient.swift — kept as a verbatim port so server-side changes only
// have to happen in one place. Auth is the user's OAuth access token.

enum LobuWorkerIdentity {
    private static let key = "lobu.workerId"
    static func current() -> String {
        if let existing = UserDefaults.standard.string(forKey: key), !existing.isEmpty {
            return existing
        }
        let generated = "mac-\(UUID().uuidString.lowercased())"
        UserDefaults.standard.set(generated, forKey: key)
        return generated
    }
}

/// Response from `POST …/complete-behavior`. When `status == "resume"` the
/// run is still claimed and the Mac should re-spawn the local CLI with
/// `nudge` appended to the prompt (bounded by `max_attempts`).
struct BehaviorExitReport: Decodable {
    let ok: Bool?
    let status: String
    let reason_code: String?
    let attempt: Int?
    let max_attempts: Int?
    let nudge: String?
    let error: String?
    let window_id: Int?
    let idempotent: Bool?

    var shouldResume: Bool { status == "resume" }
}

struct WorkerJob: Decodable {
    let run_id: Int
    let run_type: String?
    /// Behavior runs (`run_type == "behavior"`) have no connector_key — the
    /// device-side dispatcher routes them by `payload.watcher.agent_kind`
    /// (poll still nests meta under the wire key `watcher`). Connector lanes
    /// still get a string here.
    let connector_key: String?
    let feed_key: String?
    let feed_id: Int?
    let connection_id: Int?
    let operation_key: String?
    let action_input: [String: AnyJSONValue]?
    let config: [String: AnyJSONValue]?
    let checkpoint: [String: AnyJSONValue]?

    enum CodingKeys: String, CodingKey {
        case run_id
        case run_type
        case connector_key
        case feed_key
        case feed_id
        case connection_id
        case operation_key
        case action_key

        body: Body(
            run_id: runId,
            worker_id: workerId,
            status: error == nil ? "success" : "failed",
            action_output: output,
            error_message: error
        )
    )
}

/// Device-side EXIT REPORT. Posts to
/// `/api/workers/me/runs/:runId/complete-behavior` after the spawned CLI
/// exits. The agent completes the run itself via lobu CLI / MCP
/// (`completeWindow`); the server stamps exit metadata, returns
/// `status: "resume"` when finalize budget remains, or fails when the
/// agent never called completeWindow and budget is exhausted.
func completeBehaviorRun(
    workerId: String,
    runId: Int,
    output: String,
    error: String?,
    durationMs: Int,
    exitCode: Int? = nil,
    exitSignal: String? = nil,
    exitReason: String? = nil
) async throws -> BehaviorExitReport {
    struct Body: Encodable {
        let worker_id: String
        let output: String
        let error: String?
        let duration_ms: Int
        let exit_code: Int?
        let exit_signal: String?
        let exit_reason: String?
    }
    let data = try await post(
        "/api/workers/me/runs/\(runId)/complete-behavior",
        body: Body(
            worker_id: workerId,
            output: output,
            error: error,
            duration_ms: durationMs,
            exit_code: exitCode,
            exit_signal: exitSignal,
            exit_reason: exitReason
        )
    )
    if let report = try? decoder.decode(BehaviorExitReport.self, from: data) {
        return report
    }
    // Older gateways may return a minimal body — treat as non-resume.
    return BehaviorExitReport(
        ok: true,
        status: "completed",
        reason_code: nil,
        attempt: nil,
        max_attempts: nil,
        nudge: nil,
        error: nil,
        window_id: nil,
        idempotent: nil
    )
}

// MARK: REST — org-scoped endpoints (require mcp:read scope on the token)

func listNotifications(orgSlug: String, limit: Int = 10, unreadOnly: Bool = false) async throws -> LobuNotificationsResponse {
    var components = URLComponents(string: "\(baseURL.trimmedTrailingSlash())/api/\(orgSlug)/notifications")!
    components.queryItems = [
        URLQueryItem(name: "limit", value: String(limit)),
        URLQueryItem(name: "unread_only", value: unreadOnly ? "true" : "false"),
    ]
    let data = try await getRaw(url: components.url!, path: "/notifications")
    return try decoder.decode(LobuNotificationsResponse.self, from: data)
}

func getUnreadCount(orgSlug: String) async throws -> Int {
    let url = URL(string: "\(baseURL.trimmedTrailingSlash())/api/\(orgSlug)/notifications/unread-count")!
    let data = try await getRaw(url: url, path: "/notifications/unread-count")
    struct Response: Decodable { let count: Int }
    return try decoder.decode(Response.self, from: data).count
}

