    let result: ExecutorResult
    do {
        result = try await executor.run(
            payload: job.payload,
            runId: job.run_id,
            timeout: timeout,
            mcp: client.mcpWiring,
            finalizeNudge: finalizeNudge
        )
    } catch {
        // Executor failure — unambiguous, because nothing has been
        // reported yet. Missing binary is a configuration problem, not
        // a crash; keep them distinguishable in the run row so the
        // server / UI can surface "install Claude Code" vs "your CLI
        // segfaulted".
        let reason: String
        if case ExecutorBinaryError.notFound = error {
            reason = "error_message"
        } else {
            reason = "crash"
        }
        await completeWithError(
            client: client,
            workerId: workerId,
            runId: job.run_id,
            error: error.localizedDescription,
            durationMs: 0,
            exitReason: reason
        )
        return
