    // Delivery is a separate failure domain from execution. A POST that
    // throws may still have committed the transition server-side, so it
    // must never be reported as an executor error — that would fail a
    // run the server had already granted a resume to.
    guard let report = await deliverExitReport(
        client: client,
        workerId: workerId,
        runId: job.run_id,
        result: result,
        finalizeAttempt: finalizeAttempt
    ) else {
