        // and say nothing: heartbeats stop when this function returns,
        // so the server's heartbeat-stale reaper reclaims it in minutes
        // if the report never landed — and if it did land, the server's
        // own decision stands.
        NSLog(
            "[Owletto] Behavior run=%d exit report undelivered — leaving the run to the server sweep",
            job.run_id
        )
        return
    }

