/// How many times one exit report is posted before the outcome is left
/// unknown. The report is idempotent server-side (it carries
/// `finalize_attempt`), so a re-send after a lost response re-reads the
/// same decision rather than consuming another finalize attempt.
private static let exitReportDeliveryAttempts = 3
private static let exitReportRetryDelay: TimeInterval = 2

/// Post one exit report, re-sending on failures that may not have reached
/// the server. Returns nil when the outcome is still unknown, which the
/// caller must NOT convert into a failure report: the POST may already have
/// committed, and re-reporting it as an executor error would overwrite the
/// server's decision with a delivery problem.
private func deliverExitReport(
    client: WorkerClient,
    workerId: String,
    runId: Int,
    result: ExecutorResult,
    finalizeAttempt: Int
) async -> BehaviorExitReport? {
    for attempt in 0 ..< Self.exitReportDeliveryAttempts {
        do {
            return try await client.completeBehaviorRun(
                workerId: workerId,
                runId: runId,
                output: result.output,
                error: result.error,
                durationMs: result.durationMs,
                exitCode: result.exitCode.map { Int($0) },
                exitSignal: result.exitSignal,
                exitReason: result.exitReason,
                finalizeAttempt: finalizeAttempt
            )
        } catch {
            let retriable = isRetriableWorkerDeliveryFailure(error)
            NSLog(
                "[Owletto] Behavior run=%d exit report delivery failed (try %d/%d, retriable=%@): %@",
                runId,
                attempt + 1,
                Self.exitReportDeliveryAttempts,
                retriable ? "yes" : "no",
                error.localizedDescription
            )
            if !retriable { return nil }
            if attempt + 1 < Self.exitReportDeliveryAttempts {
                try? await Task.sleep(
                    nanoseconds: UInt64(
                        Self.exitReportRetryDelay
                            * Double(attempt + 1) * 1_000_000_000
                    )
                )
            }
        }
    }
    return nil
}

