// Regression test for the device Behavior exit-report delivery contract.
//
// A lost response to `complete-behavior` is an AMBIGUOUS outcome: the server may
// already have granted a resume. The dispatcher must re-send the same report
// (which is idempotent server-side via `finalize_attempt`) rather than report an
// executor error, which would fail a run the server had resumed. That decision
// hinges on isRetriableWorkerDeliveryFailure classifying "never answered" apart
// from "answered, and this is the answer".
//
//   swiftc apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Owletto/DeviceConnectorManifests.swift \
//          apps/mac/Tests/ExitReportDeliveryTests.swift -o /tmp/exitreport-test \
//   && /tmp/exitreport-test

import Foundation

// Minimal stubs for unrelated LobuClient references — same shape as
// AnyEncodableTests, so the real client compiles without the SwiftUI app graph.
struct McpWiring {
    let url: String
    let bearer: String
}

extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
}

private struct TransportFailure: Error {}

@main
struct ExitReportDeliveryTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("FAIL: \(msg)\n".utf8))
        }
    }

    static func main() throws {
        // Never answered → the server may or may not have committed, so ask again.
        check(
            isRetriableWorkerDeliveryFailure(
                URLError(.networkConnectionLost)
            ),
            "a dropped connection must be retried — the report may not have landed"
        )
        check(
            isRetriableWorkerDeliveryFailure(URLError(.timedOut)),
            "a timeout must be retried — the ambiguous case this whole path exists for"
        )
        check(
            isRetriableWorkerDeliveryFailure(TransportFailure()),
            "an unrecognized transport error must be retried, not assumed answered"
        )

        // Server asked to be asked again.
        check(
            isRetriableWorkerDeliveryFailure(
                WorkerClientError.http("/complete-behavior", 502, "")
            ),
            "5xx must be retried"
        )
        check(
            isRetriableWorkerDeliveryFailure(
                WorkerClientError.http("/complete-behavior", 429, "")
            ),
            "429 must be retried"
        )

        // The server answered; re-sending only repeats the same answer.
        check(
            !isRetriableWorkerDeliveryFailure(
                WorkerClientError.http("/complete-behavior", 409, "")
            ),
            "409 is a decided answer, not a retry"
        )
        check(
            !isRetriableWorkerDeliveryFailure(
                WorkerClientError.http("/complete-behavior", 403, "")
            ),
            "403 is a decided answer, not a retry"
        )
        check(
            !isRetriableWorkerDeliveryFailure(WorkerClientError.decode("bad body")),
            "a decode failure means the server answered — re-sending re-mangles it"
        )

        // The replayed grant the server re-serves must still drive a re-spawn:
        // shouldResume is what the dispatcher branches on, and `nudge` is what it
        // feeds the next CLI prompt.
        let replayed = """
        {"ok":true,"status":"resume","reason_code":"missing_complete_window",
         "attempt":1,"max_attempts":1,"nudge":"call completeWindow","idempotent":true}
        """
        let report = try JSONDecoder().decode(
            BehaviorExitReport.self, from: Data(replayed.utf8)
        )
        check(report.shouldResume, "a replayed resume must still be treated as a resume")
        check(report.attempt == 1, "the replayed grant keeps its attempt index")
        check(report.idempotent == true, "the replay is flagged idempotent")
        check(report.nudge == "call completeWindow", "the re-served nudge must survive decoding")

        if failures == 0 {
            print("ExitReportDeliveryTests: all checks passed")
            exit(0)
        }
        FileHandle.standardError.write(
            Data("ExitReportDeliveryTests: \(failures) failure(s)\n".utf8)
        )
        exit(1)
    }
}

