/// The completion contract appended to a Behavior prompt, chosen by how the
/// run finishes.
///
/// Window runs complete through `completeWindow`: the CLI has the gateway's
/// lobu MCP server wired in (--mcp-config) and finalizes the run itself, so
/// a run whose agent never calls it is resumed and then failed by the
/// server. The contract is part of the task, not a formatting nicety.
///
/// Event turns have no window — the reply IS the work, and the server
/// completes the run on a clean exit. Handing them the window contract made
/// the agent mint a canvas for a conversational turn and complete through
/// the window path, so the server's no-window branch never ran.
static func completionContract(payload: WatcherPayload, runId: Int) -> String {
    if payload.isEventTurn {
        return DeviceBehaviorPrompt.turnContract()
    }
    return DeviceBehaviorPrompt.completionContract(
        behaviorId: payload.watcher.id,
        runId: runId,
        extractionSchema: payload.watcher.extraction_schema
    )
}

