    static var onGrant: ((String) -> Void)?
    /// Web SPA asks this device to stop advertising a capability so the server
    /// pauses its feed (the app would otherwise re-advertise on the next poll).
    static var onRevoke: ((String) -> Void)?
    /// Web SPA asks this device to poll immediately (no permission prompts).
    static var onSync: (() -> Void)?

    static func handle(_ url: URL) {
        guard url.scheme == "owletto" else { return }
        // For grant/revoke the capability slug is the single path component,
        // e.g. owletto://grant/calendar → "calendar".
        let slug = url.path.hasPrefix("/") ? String(url.path.dropFirst()) : url.path
        switch url.host {
        case "feeds":
            switch url.path {
            // owletto://feeds/add
            case "/add":
                DispatchQueue.main.async { onAddFolder?() }
            // owletto://feeds/remove?folder_id=<id> — the device owns the
            // bookmark, so removal has to happen here or the next reconcile
            // would recreate the server feed.
            case "/remove":
                let folderId = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                    .queryItems?.first(where: { $0.name == "folder_id" })?.value
                if let folderId, !folderId.isEmpty {
                    DispatchQueue.main.async { onRemoveFolder?(folderId) }
                }
            default:
                break
            }
        // owletto://grant/<capability> — show the native permission prompt for
        // a device source. The capability auto-advertises once granted and
        // device-reconcile wires its feed server-side.
        case "grant":
            if !slug.isEmpty { DispatchQueue.main.async { onGrant?(slug) } }
        // owletto://revoke/<capability> — soft-disable so the capability stops
        // being advertised; device-reconcile pauses its feed.
        case "revoke":
            if !slug.isEmpty { DispatchQueue.main.async { onRevoke?(slug) } }
        case "sync":
            DispatchQueue.main.async { onSync?() }
        default:
            break
        }
    }
}

final class AppDelegate: NSObject, NSApplicationDelegate {
    func application(_ application: NSApplication, open urls: [URL]) {
        for url in urls { DeepLinkRouter.handle(url) }
    }
}

