                            if let err = run.error_message, !err.isEmpty {
                                Text(err)
                                    .font(.caption2)
                                    .foregroundStyle(.orange)
                                    .lineLimit(1)
                            }
                        }
                        Spacer()
                        if let ts = run.completed_at ?? run.created_at {
                            Text(relativeTime(ts))
                                .font(.caption2)
                                .foregroundStyle(.tertiary)
                        }
                    }
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .menuRow()
            }
        }
    }
