private func runDisplayLabel(_ run: LobuRun) -> String {
    if let op = run.operation_key, !op.isEmpty {
        if let conn = run.connector_key, !conn.isEmpty { return "\(conn) · \(op)" }
        return op
    }
    return run.connector_key ?? "run #\(run.id)"
}

private func runStatusColor(_ status: String?) -> Color {
    switch status {
    case "completed", "success": return .green
    case "failed", "error":      return .red
    case "running":              return .yellow
    case "pending":              return .gray
    default:                     return .secondary
    }
}

private func openRun(_ run: LobuRun) {
    guard let slug = state.deviceOrgSlug, !slug.isEmpty else { return }
    // There is no `/runs/:id` route in the web app — a run is viewed on the
    // Memory page filtered by `run_ids` (the same target as the web's own
    // "View in memory" link). The old `/<slug>/runs/<id>` URL fell through
    // the `$owner/$` catch-all and resolved to a bogus entity page.
    if let url = webDeepLinkURL(path: "/\(slug)/memory?run_ids=\(run.id)") {
        NSWorkspace.shared.open(url)
    }
}

