/// A permission/scope list that shows only the first `limit` badges until the
/// user asks for the rest. Slack alone ships 30+ scopes, which pushed the
/// connect button below the fold and made the form read as a wall of tokens.
/// Collapsed is the default because the exact scope strings are reference
/// material — you check them deliberately, you don't scan them every time.
function CollapsibleBadgeList({
	items,
	variant,
	limit = 6,
}: {
	items: string[];
	variant: "secondary" | "outline";
	limit?: number;
}) {
	const [expanded, setExpanded] = useState(false);
	const overflow = items.length - limit;
	const visible = expanded ? items : items.slice(0, limit);

	return (
		<div className="flex flex-wrap items-center gap-1.5">
			{visible.map((item) => (
				<Badge
					key={item}
					variant={variant}
					className="text-[10px] px-1.5 py-0 h-5"
				>
					{item}
				</Badge>
			))}
			{overflow > 0 && (
				<Button
					variant="ghost"
					size="sm"
					onClick={() => setExpanded((prev) => !prev)}
					className="h-5 px-1.5 text-[10px] text-muted-foreground"
				>
					{expanded ? "Show less" : `+${overflow} more`}
				</Button>
			)}
		</div>
	);
}

