/// Re-probe the WhatsApp archive off the main actor and publish the result.
/// Fire-and-forget: the probe may sit on a TCC dialog for as long as it takes
/// the user to answer, and the app must stay fully usable meanwhile.
///
/// Probes ONCE per launch unless forced. Opening the archive is what triggers
/// the TCC dialog, so a probe on every poll is a dialog on every poll — and
/// `effectiveAutoPollInterval` drops to 10s whenever computer use is active,
/// which is most of the time on a paired Mac. Whether WhatsApp Desktop has an
/// archive on disk does not change at poll frequency; it changes when the user
/// grants access, which is exactly when `force` is passed.
func refreshWhatsAppAvailability(force: Bool = false) {
    guard !whatsAppDisabled else {
        whatsAppArchiveReadable = false
        whatsAppProbeDone = false
        return
    }
    guard force || !whatsAppProbeDone else { return }
    whatsAppProbeDone = true
    Task.detached(priority: .utility) { [weak self] in
        let readable = WhatsAppLocalSyncService.isAvailable()
        await MainActor.run { self?.whatsAppArchiveReadable = readable }
    }
}

