import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

/**
 * A permission/scope list that shows only the first `limit` badges until the
 * user asks for the rest. Slack alone ships 30+ scopes, which pushed the connect
 * button below the fold and made the form read as a wall of tokens. Collapsed is
 * the default because the exact scope strings are reference material — you check
 * them deliberately, you don't scan them every time.
 */
export function CollapsibleBadgeList({
	items,
	variant,
	limit = 6,
}: {
	items: string[];
	variant: "secondary" | "outline";
	limit?: number;
}) {
	const [expanded, setExpanded] = useState(false);
	const overflow = items.length - limit;
	const visible = expanded ? items : items.slice(0, limit);

	return (
		<div className="flex flex-wrap items-center gap-1.5">
			{visible.map((item) => (
				<Badge
					key={item}
					variant={variant}
					className="text-[10px] px-1.5 py-0 h-5"
				>
					{item}
				</Badge>
			))}
			{overflow > 0 && (
				<Button
					variant="ghost"
					size="sm"
					onClick={() => setExpanded((prev) => !prev)}
					className="h-5 px-1.5 text-[10px] text-muted-foreground"
				>
					{expanded ? "Show less" : `+${overflow} more`}
				</Button>
			)}
		</div>
	);
}

// @vitest-environment jsdom
import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { CollapsibleBadgeList } from "./collapsible-badge-list";

const SLACK_SCOPES = [
	"channels:history",
	"channels:read",
	"chat:write",
	"files:read",
	"groups:history",
	"groups:read",
	"im:history",
	"im:read",
	"users:read",
	"team:read",
];

describe("CollapsibleBadgeList", () => {
	it("shows only the first `limit` items and counts the rest", () => {
		render(<CollapsibleBadgeList items={SLACK_SCOPES} variant="secondary" />);

		expect(screen.getByText("channels:history")).toBeTruthy();
		expect(screen.getByText("groups:read")).toBeTruthy();
		// 7th onward is hidden until asked for.
		expect(screen.queryByText("im:history")).toBeNull();
		expect(screen.queryByText("team:read")).toBeNull();
		expect(screen.getByRole("button").textContent).toBe("+4 more");
	});

	it("reveals every item when expanded, and re-collapses", () => {
		render(<CollapsibleBadgeList items={SLACK_SCOPES} variant="secondary" />);

		fireEvent.click(screen.getByRole("button"));
		for (const scope of SLACK_SCOPES) {
			expect(screen.getByText(scope)).toBeTruthy();
		}
		expect(screen.getByRole("button").textContent).toBe("Show less");

		fireEvent.click(screen.getByRole("button"));
		expect(screen.queryByText("team:read")).toBeNull();
		expect(screen.getByRole("button").textContent).toBe("+4 more");
	});

	it("renders no toggle when the list fits", () => {
		render(
			<CollapsibleBadgeList
				items={SLACK_SCOPES.slice(0, 6)}
				variant="outline"
			/>,
		);

		expect(screen.getByText("groups:read")).toBeTruthy();
		expect(screen.queryByRole("button")).toBeNull();
	});

	it("renders no toggle at exactly the limit boundary", () => {
		// overflow === 0 must not render a "+0 more" control.
		render(
			<CollapsibleBadgeList
				items={SLACK_SCOPES.slice(0, 3)}
				variant="outline"
				limit={3}
			/>,
		);

		expect(screen.queryByRole("button")).toBeNull();
	});

	it("honours a custom limit", () => {
		render(
			<CollapsibleBadgeList
				items={SLACK_SCOPES}
				variant="secondary"
				limit={2}
			/>,
		);

		expect(screen.getByText("channels:read")).toBeTruthy();
		expect(screen.queryByText("chat:write")).toBeNull();
		expect(screen.getByRole("button").textContent).toBe("+8 more");
	});
});

