export default async (ctx, client) => {
  const conns = await client.connections.list();
  return conns
    .filter((c: any) => String(c.connector_key || "").includes("computer"))
    .map((c: any) => ({ id: c.id, slug: c.slug, key: c.connector_key, status: c.status, device: c.device_worker_id }));
}

export default async (ctx, client) => {
  const res: any = await client.connections.list();
  const rows = Array.isArray(res) ? res : (res.items ?? res.connections ?? res.data ?? []);
  return {
    shape: Array.isArray(res) ? "array" : Object.keys(res),
    computerUse: rows
      .filter((c: any) => String(c.connector_key || "").includes("computer"))
      .map((c: any) => ({ id: c.id, slug: c.slug, key: c.connector_key, status: c.status })),
  };
}

export default async (ctx, client) => {
  const avail: any = await client.operations.listAvailable({ connection_id: 447 });
  const ops = Array.isArray(avail) ? avail : (avail.operations ?? avail.items ?? []);
  return {
    keys: ops.map((o: any) => o.key ?? o.operation_key).slice(0, 40),
    targets: avail.targets ?? avail.execution_targets ?? undefined,
  };
}

export default async (ctx, client) => {
  const res: any = await client.operations.execute({
    connection_id: 447,
    operation_key: "permissions",
  });
  return res;
}

