/// Header + full-label chips in a 2-row wrap (no truncation).
private var permissionsSection: some View {
    // Touch refresh token so SwiftUI re-reads live TCC probes.
    let _ = permissionsRefreshToken
    return VStack(alignment: .leading, spacing: 4) {
        Text("PERMISSIONS")
            .font(.caption2)
            .foregroundStyle(.tertiary)
            .fontWeight(.semibold)
            .tracking(0.4)
            .padding(.horizontal, 8)
        // Fixed 2-row layout: full titles, never line-limit truncate.
        // Row 1: computer-use gates · Row 2: optional + session.
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                permissionChip(kind: .screenRecording)
                permissionChip(kind: .control)
                Spacer(minLength: 0)
            }
            HStack(spacing: 6) {
                permissionChip(kind: .fullDiskAccess)
                permissionChip(kind: .notifications)
                permissionChip(kind: .openAtLogin)
                Spacer(minLength: 0)
            }
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 2)
    }
}

private func permissionChip(kind: DevicePermissionKind) -> some View {
    let granted = kind.isGranted
    return Button {
        let msg = kind.requestGrant()
        // Empty msg = already granted / chip state is enough — no status spam.
        if !msg.isEmpty { state.setStatus(msg) }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 500_000_000)
            if kind == .notifications {
                await DevicePermissionKind.refreshNotificationStatus()
            }
            permissionsRefreshToken &+= 1
            if kind == .screenRecording || kind == .control {
                state.computerUseEnabled = true
                state.computerUseDisabled = false
                await state.syncNow()
            }
        }
    } label: {
        HStack(spacing: 4) {
            Image(systemName: granted ? "checkmark.circle.fill" : "circle")
                .font(.caption2)
                .foregroundStyle(granted ? .green : (kind.isRequiredForComputerUse ? .orange : .secondary))
            Text(kind.title)
                .font(.caption2)
                .foregroundStyle(granted ? .primary : .secondary)
                .lineLimit(1)
                .fixedSize(horizontal: true, vertical: false)
        }
        .padding(.horizontal, 7)
        .padding(.vertical, 5)
        .background(
            RoundedRectangle(cornerRadius: 6, style: .continuous)
                .fill(Color.primary.opacity(granted ? 0.06 : 0.04))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 6, style: .continuous)
                .strokeBorder(
                    granted
                        ? Color.green.opacity(0.35)
                        : (kind.isRequiredForComputerUse ? Color.orange.opacity(0.4) : Color.secondary.opacity(0.2)),
                    lineWidth: 0.5
                )
        )
        .contentShape(Rectangle())
        .help(
            granted
                ? (kind == .openAtLogin
                    ? "\(kind.title): on — click to turn off."
                    : "\(kind.title): on — click to open System Settings and uncheck Owletto.")
                : "\(kind.title) — click to enable. \(kind.subtitle)"
        )
    }
    .buttonStyle(.plain)

            footerRow
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 8)
        .frame(width: 340)
        .onAppear {
            permissionsRefreshToken &+= 1
            Task {
                await DevicePermissionKind.refreshNotificationStatus()
                await MainActor.run { permissionsRefreshToken &+= 1 }
            }
        }
    }

    private var sectionDivider: some View {
        Divider().padding(.vertical, 6).padding(.horizontal, 6)
    }

