import Foundation
import OSLog

/// Central logging for the Mac app.
///
/// Two sinks, both deliberate:
///
/// 1. `os.Logger`, so `log show --predicate 'subsystem == "ai.lobu.mac"'` works.
///    Interpolations are marked `privacy: .public` — the default is `.private`,
///    which renders every value as `<private>` and is why unified-log output
///    looks empty even when the app is talking.
/// 2. A file at `~/Library/Logs/Owletto/owletto.log`, because Owletto is an
///    `LSUIElement` bundle launched by LaunchServices: stdout is discarded, so
///    the `print()` calls this replaces produced nothing anyone could hand back
///    to us when something broke.
///
/// **File writes never touch the calling thread's filesystem.** They are queued
/// onto a serial background queue. `AppState` is `@MainActor`, and a blocking
/// `open()` there is precisely what previously parked the menu bar, the poll
/// loop and the heartbeat when TCC re-evaluated the binary — a logger that can
/// hang the app is worse than no logger.
enum Log {
    enum Category: String {
        case app
        case sync
        case worker
        case permissions
        case connector
        case whatsapp
    }

    private static let subsystem = "ai.lobu.mac"

    private static var loggers: [Category: Logger] = [:]
    private static let loggerLock = NSLock()

    private static func logger(for category: Category) -> Logger {
        loggerLock.lock()
        defer { loggerLock.unlock() }
        if let existing = loggers[category] { return existing }
        let made = Logger(subsystem: subsystem, category: category.rawValue)
        loggers[category] = made
        return made
    }

    // MARK: - Public API

    static func debug(_ category: Category, _ message: String) {
        logger(for: category).debug("\(message, privacy: .public)")
        appendToFile(level: "DEBUG", category: category, message: message)
    }

    static func info(_ category: Category, _ message: String) {
        logger(for: category).info("\(message, privacy: .public)")
        appendToFile(level: "INFO", category: category, message: message)
    }

    static func error(_ category: Category, _ message: String) {
        logger(for: category).error("\(message, privacy: .public)")
        appendToFile(level: "ERROR", category: category, message: message)
    }

    /// Absolute path of the log file, for surfacing in the UI so a user can
    /// find it without being told a path over chat.
    static var fileURL: URL {
        directoryURL.appendingPathComponent("owletto.log")
    }

    // MARK: - File sink

    private static let queue = DispatchQueue(label: "ai.lobu.mac.log", qos: .utility)

    /// Rotate at 5 MB, keeping one previous file. Bounded on purpose: this runs
    /// on every user's machine forever and nothing prunes it but us.
    private static let maxBytes: UInt64 = 5 * 1024 * 1024

    private static let directoryURL: URL = {
        URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Logs/Owletto", isDirectory: true)
    }()

    private static let timestampFormatter: ISO8601DateFormatter = {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return f
    }()

    private static func appendToFile(level: String, category: Category, message: String) {
        let stamp = timestampFormatter.string(from: Date())
        let line = "\(stamp) [\(level)] [\(category.rawValue)] \(message)\n"
        queue.async {
            write(line)
        }
    }

    /// Called only on `queue`.
    private static func write(_ line: String) {
        let fm = FileManager.default
        if !fm.fileExists(atPath: directoryURL.path) {
            try? fm.createDirectory(at: directoryURL, withIntermediateDirectories: true)
        }
        let url = fileURL
        rotateIfNeeded(at: url, fm: fm)
        guard let data = line.data(using: .utf8) else { return }
        if let handle = try? FileHandle(forWritingTo: url) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: data)
        } else {
            try? data.write(to: url, options: .atomic)
        }
    }

    /// Called only on `queue`.
    private static func rotateIfNeeded(at url: URL, fm: FileManager) {
        guard let attrs = try? fm.attributesOfItem(atPath: url.path),
              let size = attrs[.size] as? UInt64,
              size >= maxBytes
        else { return }
        let rotated = url.deletingLastPathComponent().appendingPathComponent("owletto.log.1")
        try? fm.removeItem(at: rotated)
        try? fm.moveItem(at: url, to: rotated)
    }
}

