    let missing = kind.unmetRequirements
    let detail = missing.count > 1 || missing != [kind.title]
        ? " Missing: \(missing.joined(separator: ", "))."
        : ""
    return "\(kind.title) — click to enable. \(kind.subtitle)\(detail)"
