/// Last file line written, and how many identical ones have been swallowed
/// since. Touched only on `queue`.
private static var lastKey = ""
private static var repeatCount = 0

private static func appendToFile(level: String, category: Category, message: String) {
    let stamp = timestampFormatter.string(from: Date())
    let key = "\(level)|\(category.rawValue)|\(message)"
    queue.async {
        // Collapse consecutive identical lines. The poll loop runs every 10s
        // under computer use, so a sustained outage writes the same sentence
        // hundreds of times and buries the state change that explains it.
        // Repeats are counted and flushed when the message finally differs,
        // so nothing is silently lost. os.Logger still receives every line —
        // the unified log is built for volume; a file a human reads is not.
        if key == lastKey {
            repeatCount += 1
            return
        }
        if repeatCount > 0 {
            write("\(stamp) [\(level)] [\(category.rawValue)] ⤷ previous line repeated \(repeatCount)×\n")
            repeatCount = 0
        }
        lastKey = key
        write("\(stamp) [\(level)] [\(category.rawValue)] \(message)\n")
    }
}

