/// When each distinct message was last written, and how many copies have
/// been suppressed since. Touched only on `queue`.
private static var recent: [String: (last: Date, suppressed: Int)] = [:]

/// How long a given message stays suppressed after being written.
private static let dedupeWindow: TimeInterval = 60

private static func appendToFile(level: String, category: Category, message: String) {
    let now = Date()
    let key = "\(level)|\(category.rawValue)|\(message)"
    queue.async {
        // Throttle per distinct message, NOT per consecutive line. The poll
        // loop emits several different errors per cycle, so identical lines
        // interleave rather than repeat back-to-back — a consecutive-only
        // check never fires against real output. Suppressed copies are
        // counted and reported when the message next gets through, so a
        // sustained outage reads as one line plus a count instead of
        // hundreds of identical sentences. os.Logger still gets every line;
        // the unified log is built for volume, a file a human reads is not.
        if let entry = recent[key], now.timeIntervalSince(entry.last) < dedupeWindow {
            recent[key] = (entry.last, entry.suppressed + 1)
            return
        }
        let suppressed = recent[key]?.suppressed ?? 0
        recent[key] = (now, 0)
        // Drop entries that have aged out so this map cannot grow unbounded
        // across a long-running session.
        if recent.count > 256 {
            recent = recent.filter { now.timeIntervalSince($0.value.last) < dedupeWindow }
        }
        let stamp = timestampFormatter.string(from: now)
        let tail = suppressed > 0 ? " (+\(suppressed) suppressed in the last \(Int(dedupeWindow))s)" : ""
        write("\(stamp) [\(level)] [\(category.rawValue)] \(message)\(tail)\n")
    }
}

