// Standalone regression test for the Log file sink's repeat suppression.
//
// The Mac app has no XCTest target, so this compiles + runs as an executable:
//
//   swiftc -parse-as-library apps/mac/Owletto/Log.swift \
//          apps/mac/Tests/LogDedupeTests.swift -o /tmp/log-dedupe-test \
//   && /tmp/log-dedupe-test
//
// It guards a fix whose first attempt was wrong in a way that looked right.
// The poll loop runs every 10s under computer use and emits SEVERAL distinct
// errors per cycle, so during an outage identical lines interleave:
//
//     reconcileFolderFeeds failed …
//     sync error …
//     reconcileFolderFeeds failed …      <- same as line 1, but not adjacent
//     sync error …
//
// A collapse-consecutive-duplicates check never fires against that shape and
// silently does nothing, which is exactly what shipped until the log was read
// back. Suppression must therefore be keyed per distinct message, not per
// adjacent line. This test reproduces the interleaving directly.
//
// `LOBU_OWLETTO_LOG_DIR` redirects the sink so this never touches the user's
// real ~/Library/Logs/Owletto/owletto.log.

import Foundation

@main
struct LogDedupeTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("  ✗ \(msg)\n".utf8))
        }
    }

    static func main() {
        let dir = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent("log-dedupe-\(UUID().uuidString)", isDirectory: true)
        setenv("LOBU_OWLETTO_LOG_DIR", dir.path, 1)
        defer { try? FileManager.default.removeItem(at: dir) }

        let a = "reconcileFolderFeeds failed: Could not connect to the server."
        let b = "sync error: Could not connect to the server."

        // Interleave two distinct messages: never adjacent to themselves.
        for _ in 0..<5 {
            Log.error(.sync, a)
            Log.error(.sync, b)
        }
        // A genuinely new message must still get through immediately — the
        // suppression must not be a blanket rate limit on the whole file.
        Log.info(.worker, "capabilities=[computer_use] context=local")

        // Drain the serial write queue.
        Thread.sleep(forTimeInterval: 1.5)

        let contents = (try? String(contentsOf: Log.fileURL, encoding: .utf8)) ?? ""
        let lines = contents.split(separator: "\n").map(String.init)

        check(lines.filter { $0.contains(a) }.count == 1,
              "message A logged 5× interleaved must appear once; got \(lines.filter { $0.contains(a) }.count)")
        check(lines.filter { $0.contains(b) }.count == 1,
              "message B logged 5× interleaved must appear once; got \(lines.filter { $0.contains(b) }.count)")
        check(lines.contains { $0.contains("capabilities=[computer_use]") },
              "a distinct message must not be suppressed by unrelated traffic")
        check(lines.count == 3,
              "expected exactly 3 lines, got \(lines.count): \(lines)")
        // Category and level must survive into the file, since grepping by them
        // is the whole point of having categories.
        check(lines.contains { $0.contains("[ERROR] [sync]") },
              "level and category must be present on error lines")
        check(lines.contains { $0.contains("[INFO] [worker]") },
              "level and category must be present on info lines")

        if failures == 0 {
            print("LogDedupeTests: all checks passed")
            exit(0)
        } else {
            FileHandle.standardError.write(Data("LogDedupeTests: \(failures) failure(s)\n".utf8))
            exit(1)
        }
    }
}

