export default async (ctx, client) => {
  const r = await client.operations.execute({ connection_id: 447, operation_key: "permissions" });
  return { status: r?.status, perms: (r?.output?.data?.permissions || []).map(p => `${p.name}=${p.isGranted}`) };
}

export default async (ctx, client) => {
  const r = await client.behaviors.list({ limit: 50 });
  const rows = r.behaviors || r.data || r.items || r || [];
  return (Array.isArray(rows) ? rows : []).map(b => ({ id: b.id, name: b.name, enabled: b.enabled ?? b.is_enabled, agent: b.agent_kind, device: b.device_worker_id || b.pinned_device_id }));
}

export default async (ctx, client) => {
  const r = await client.behaviors.list({ limit: 50 });
  const rows = r.behaviors || r.data || r.items || r || [];
  const b = (Array.isArray(rows) ? rows : []).find(x => String(x.name).includes("agy e2e"));
  return { keys: Object.keys(b || {}), behavior: b };
}

