/// `~/Library/Logs/Owletto` normally. Overridable so tests can exercise the
/// file sink without writing to — or truncating — the user's real log.
/// Naming matches the existing `LOBU_OWLETTO_*` variables in `OwlettoApp`.
///
/// The real log is reserved for the real app. Every standalone test under
/// `apps/mac/Tests` compiles the production sources it exercises — including
/// this file — so without a guard here their scripted failures land in the
/// user's log looking exactly like production incidents. That is not
/// hypothetical: `DispatcherResumeTests` scripts a 503, a 400 and an
/// `<html>502</html>` against run 4242, and reading those lines back out of
/// `~/Library/Logs/Owletto/owletto.log` cost a full debugging session
/// chasing a wedged run that never existed.
///
/// The env override alone could not fix that: it only protects tests that
/// remember to set it, and the file headers document a bare `swiftc`
/// invocation a human can paste without it. So the decision lives here,
/// where every caller passes regardless of how the binary was launched: only
/// the signed app bundle writes to the user's log, everything else gets a
/// scratch directory it is free to fill.
private static let directoryURL: URL = {
    if let override = ProcessInfo.processInfo.environment["LOBU_OWLETTO_LOG_DIR"],
       !override.isEmpty {
        return URL(fileURLWithPath: override, isDirectory: true)
    }
    guard Bundle.main.bundleIdentifier == appBundleIdentifier else {
        return URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
            .appendingPathComponent("owletto-log-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
    }
    return URL(fileURLWithPath: NSHomeDirectory())
        .appendingPathComponent("Library/Logs/Owletto", isDirectory: true)
}()

/// Bundle id of the shipping app. A test executable has either no bundle id
/// or its own, never this one.
private static let appBundleIdentifier = "ai.lobu.mac"

