// Standalone regression test: a test binary must never write to the user's log.
//
//   swiftc -parse-as-library apps/mac/Owletto/Log.swift \
//          apps/mac/Tests/LogSinkIsolationTests.swift -o /tmp/log-sink-isolation-test \
//   && /tmp/log-sink-isolation-test
//
// Every standalone test under apps/mac/Tests compiles the production sources it
// exercises, and several of them (WatcherDispatcher, LobuClient) transitively
// pull in Log.swift. Before the guard this pins, those tests appended their
// SCRIPTED failures to ~/Library/Logs/Owletto/owletto.log — the same file the
// app writes and the same file a human reads when something breaks.
//
// That is not a tidiness problem, it is a correctness problem for debugging.
// `DispatcherResumeTests` scripts a 503, a 400 and an `<html>502</html>` against
// run 4242 and drives the local resume cap through 8 rounds. Read back out of
// the real log those lines are indistinguishable from a production incident:
// they cost a full session diagnosing a wedged Behavior run that never existed,
// and produced a confident report of three bugs that were all assertions
// passing.
//
// `LOBU_OWLETTO_LOG_DIR` could not fix this on its own — it only protects tests
// that remember to set it, and every test header documents a bare swiftc line a
// human can paste without it. So the guard lives in the sink: only the signed
// app bundle resolves to the user's log. This test asserts the default path
// with NO override set, because that is the configuration that broke.

import Foundation

@main
struct LogSinkIsolationTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("  ✗ \(msg)\n".utf8))
        }
    }

    static func main() {
        // The configuration under test: no redirect, exactly as a pasted swiftc
        // invocation would run.
        unsetenv("LOBU_OWLETTO_LOG_DIR")

        let realLog = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Logs/Owletto/owletto.log")

        // Compare by size, not existence: the user's real log usually DOES exist
        // and asserting on its absence would pass for the wrong reason on a
        // clean machine while failing for a real user.
        let sizeBefore = byteSize(of: realLog)

        // A marker unique per run, so a stale copy from an earlier build cannot
        // make this pass or fail by accident.
        let marker = "log-sink-isolation-probe-\(UUID().uuidString)"
        Log.error(.worker, marker)
        Log.info(.app, marker)

        // The sink writes on a background serial queue; give it room to land.
        Thread.sleep(forTimeInterval: 1.5)

        let sizeAfter = byteSize(of: realLog)
        check(
            sizeAfter == sizeBefore,
            "a test binary grew the user's real log by \(sizeAfter - sizeBefore) bytes "
                + "(\(realLog.path)) — the sink must refuse it outside the app bundle")

        if let contents = try? String(contentsOf: realLog, encoding: .utf8) {
            check(
                !contents.contains(marker),
                "the probe line reached the user's real log at \(realLog.path)")
        }

        // The lines must still go SOMEWHERE — a guard that silently drops every
        // message would satisfy the assertions above while destroying the file
        // sink for the tests that legitimately exercise it.
        let fallback = URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
            .appendingPathComponent(
                "owletto-log-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
            .appendingPathComponent("owletto.log")
        let redirected = (try? String(contentsOf: fallback, encoding: .utf8)) ?? ""
        check(
            redirected.contains(marker),
            "the redirected sink at \(fallback.path) did not receive the line — "
                + "the guard must redirect the file sink, not disable it")

        try? FileManager.default.removeItem(at: fallback.deletingLastPathComponent())

        if failures == 0 {
            print("LogSinkIsolationTests: all checks passed")
        } else {
            FileHandle.standardError.write(Data("LogSinkIsolationTests: \(failures) failure(s)\n".utf8))
            exit(1)
        }
    }

    private static func byteSize(of url: URL) -> Int {
        let attrs = try? FileManager.default.attributesOfItem(atPath: url.path)
        return (attrs?[.size] as? Int) ?? 0
    }
}

