/// Pure form of the rule above, taking its two inputs as parameters.
///
/// Not private, and not a test-only affordance: the bug this exists to
/// prevent was invisible to a test that could only observe
/// `Bundle.main.bundleIdentifier` of its OWN process. A standalone test
/// binary is always the "not an app" case, so it exercised one branch and
/// reported the guard healthy while the app branch was broken. Passing the
/// identifier in is what makes both branches assertable.
static func resolveDirectory(bundleIdentifier: String?, override: String?) -> URL {
    if let override, !override.isEmpty {
        return URL(fileURLWithPath: override, isDirectory: true)
    }
    guard bundleIdentifier != nil else {
        return URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
            .appendingPathComponent(
                "owletto-log-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
    }
    return URL(fileURLWithPath: NSHomeDirectory())
        .appendingPathComponent("Library/Logs/Owletto", isDirectory: true)
}

