private static func byteSize(of url: URL) -> Int {
    let attrs = try? FileManager.default.attributesOfItem(atPath: url.path)
    return (attrs?[.size] as? Int) ?? 0
}

/// The half this test could not see before, and the half that shipped broken.
///
/// The redirect assertions below observe `Bundle.main.bundleIdentifier` of
/// THIS process, which is always nil — so they exercise the "not an app"
/// branch only. The first version of the guard compared the bundle id
/// against a hardcoded `"ai.lobu.mac"`, which is the os.Logger *subsystem*;
/// the real `PRODUCT_BUNDLE_IDENTIFIER` is `com.owletto.mac`. Every
/// assertion here passed while the shipping app silently wrote its logs to
/// a temp directory.
///
/// So drive the decision function directly with identifiers this process
/// can never have. The literals are deliberate: `com.owletto.mac` is the
/// real one, and `ai.lobu.mac` is the value that was wrongly treated as
/// authoritative — if someone reintroduces an equality check against either
/// constant, one of these cases fails.
private static func checkAppStillGetsTheRealLog() {
    let realLogDir = URL(fileURLWithPath: NSHomeDirectory())
        .appendingPathComponent("Library/Logs/Owletto")

    for bundleId in ["com.owletto.mac", "ai.lobu.mac", "com.example.anything"] {
        let resolved = Log.resolveDirectory(bundleIdentifier: bundleId, override: nil)
        check(
            resolved.standardizedFileURL == realLogDir.standardizedFileURL,
            "a bundled process (\(bundleId)) must write to \(realLogDir.path), got \(resolved.path)")
    }

    let unbundled = Log.resolveDirectory(bundleIdentifier: nil, override: nil)
    check(
        unbundled.standardizedFileURL != realLogDir.standardizedFileURL,
        "an unbundled binary must NOT resolve to the user's log, got \(unbundled.path)")

    // The override still wins over both branches — that is what lets
    // LogDedupeTests exercise the file sink against a scratch directory.
    let overridden = Log.resolveDirectory(bundleIdentifier: "com.owletto.mac", override: "/tmp/x")
    check(
        overridden.path == "/tmp/x",
        "LOBU_OWLETTO_LOG_DIR must win even for a bundled process, got \(overridden.path)")
}

